message.content:
{
  "pitches": [
    {
      "key": "pc_irrigation_route",
      "title": "물길의 갈림길",
      "situation": "미식전이 쌀 농사를 돕던 중, 가뭄으로 인해 물길을 새로 내야 하는 상황에 직면한다. 농작물을 살리기 위해 물을 끌어올 수 있는 두 갈래 길 중 하나는 지형이 험해 시간이 더 걸리고, 다른 하나는 인근 마을의 공유 수로를 일부 빌려 써야 하는 민감한 경로다.",
      "canonConnection": "미식전의 쌀 농사 소재를 활용.",
      "whyDifferent": "단순 수확이 아닌, 자원의 배분과 타인과의 이해관계(물권)를 조정하는 의사결정 문제.",
      "uncertain": ["인근 마을 주민들이 수로 사용에 대해 얼마나 방어적일지 알 수 없음."],
      "actions": [
        {"action": "험로를 개척한다", "result": "노동력 소모가 크지만 마을과의 마찰이 없음. (비용: 체력 소모량 증가 / 보상: 농작물 품질 유지)", "rewardRole": "노동 효율 저하 및 관계 유지성 보존/변동}",
        "remainingProblem": "험로 작업 중 예상치 못한 지형 붕괴로 인한 추가 수리 비용 발생 가능성."
      },
    {
      "action": "공유 수로를 협의한다", "result": "빠른 해결이 가능하나 마을의 눈치를 봐야 함. (비용: 골드 소모 / 보상: 작업 시간 단축)", "rewardRole": "마을민심(관계게이지) 변동 및 골드 소모","remainingProblem": "향후 마을 방문 시 추가적인 협조를 얻기 어려워질 수 있음."}
    ]
    },
    {
      "key": "pc_garment_misdelivery",
      "title": "엇갈린 의상 수선",
      "situation": "츠무기의 의상 가게에 미식전이 물건을 배달하려 했으나, 배달 목록과 의뢰 내용이 섞여 다른 손님의 옷을 수선해야 하는 상황이 발생한다. 츠무기는 당황하며 주문서와 실물을 대조하고 있다.",
      "canonConnection": "츠무기의 의상 가게와 유우키의 배달 소재 활용.",
      "whyDifferent": "단순 배달이 아닌, 오류 상황에서 우선순위를 정하고 책임을 분담하는 문제.",
      "uncertain": ["실제 의뢰인의 성격이나 급박한 정도를 알 수 없음."],
